    for t in d.tables:
        for row in t.rows:
            for c in row.cells:
                if '**' in c.text: badtbl.append(c.text[:60])
    print(f, "stray ** paras:", len(bad), "in tables:", len(badtbl), bad[:2], badtbl[:2])
# fix first memo table
d=docx.Document('output/drafting-issues-memorandum.docx')
t=d.tables[0]
from docx.oxml.ns import qn
grid=t._tbl.find(qn('w:tblGrid'))
for gc,w in zip(grid.findall(qn('w:gridCol')), [1.15,5.35]):
    gc.set(qn('w:w'), str(int(w*1440)))
for row in t.rows:
    for cell,w in zip(row.cells,[1.15,5.35]):
        cell.width=Inches(w)
d.save('output/drafting-issues-memorandum.docx')
print("width fix applied")
